"""Supplement explicit requirement gaps without replacing existing tests."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent;REPO=HERE.parent
cfg=json.loads((HERE/'config/application_host.json').read_text(encoding='utf-8'));manifest=json.loads((HERE/'requirements/case-manifest-application.json').read_text(encoding='utf-8'))
def add(module,req,n,sut,pre,inputs,expected,body):
 m=next(m for m in cfg['modules'] if m['module']==module);tid=req+'-ADD-'+n;name=tid.replace('-','_')
 if any(c['Test ID']==tid and c['module']==module for c in manifest):return
 p=HERE/m['test'];p.write_text(p.read_text(encoding='utf-8')+f'\n/* {tid}: {expected} */\nPST_TEST({module},{name}) {{\n{body}\n}}\n',encoding='utf-8')
 m['cases'].append(tid);m['case_count']+=1
 manifest.append({'Test ID':tid,'Requirement ID':req,'SUT':sut,'Precondition':pre,'Mock':'explicit host/unit dependency contract','Inputs':inputs,'Expected':expected,'module':module,'source':m['source'],'test_source':m['test'],'native_test':name,'status':'Authored','section':0,'purpose':'requirement-based gap'})
reset='''pst_reset_contract();memset(&mrc_state,0,sizeof(mrc_state));memset(&mrc_tablePackValues,0,sizeof(mrc_tablePackValues));memset(&mrc_tableCellVoltages,0,sizeof(mrc_tableCellVoltages));memset(&mrc_tableCellTemperatures,0,sizeof(mrc_tableCellTemperatures));memset(&mrc_tableMinimumMaximumValues,0,sizeof(mrc_tableMinimumMaximumValues));'''
module='redundancy_redundancy'
add(module,'F2-LLR-ALG-080-01','001','MRC_Initialize','zero outputs','initialize','all AFE/Pack invalid;3 DB writes;STD_OK',reset+'''
extern STD_RETURN_TYPE_e pst_rdn_write_result;pst_rdn_write_result=STD_OK;PST_EQ(MRC_Initialize(),STD_OK);PST_EQ(pst_writes,3);
for(unsigned s=0;s<BS_NR_OF_STRINGS;s++) {PST_EQ(mrc_tableCellVoltages.invalidStringVoltage[s],true);PST_EQ(mrc_tablePackValues.invalidStringVoltage[s],1);PST_EQ(mrc_tablePackValues.invalidStringCurrent[s],1);PST_EQ(mrc_tablePackValues.invalidStringPower[s],1);
for(unsigned m=0;m<BS_NR_OF_MODULES_PER_STRING;m++){PST_EQ(mrc_tableCellVoltages.invalidModuleVoltage[s][m],true);for(unsigned c=0;c<BS_NR_OF_CELL_BLOCKS_PER_MODULE;c++)PST_EQ(mrc_tableCellVoltages.invalidCellVoltage[s][m][c],true);for(unsigned t=0;t<BS_NR_OF_TEMP_SENSORS_PER_MODULE;t++)PST_EQ(mrc_tableCellTemperatures.invalidCellTemperature[s][m][t],true);}}
PST_EQ(mrc_tablePackValues.invalidPackCurrent,1);PST_EQ(mrc_tablePackValues.invalidPackPower,1);PST_EQ(mrc_tablePackValues.invalidBatteryVoltage,1);PST_EQ(mrc_tablePackValues.invalidHvBusVoltage,1);''')
manifest[-1]['Requirement ID']+='\nF2-LLR-ALG-080-02\nF2-LLR-ALG-080-03'
add(module,'F2-LLR-ALG-080-03','001','MRC_Initialize','DB write returns NOT_OK','initialize','STD_NOT_OK',reset+'''extern STD_RETURN_TYPE_e pst_rdn_write_result;pst_rdn_write_result=STD_NOT_OK;PST_EQ(MRC_Initialize(),STD_NOT_OK);PST_EQ(pst_writes,3);pst_rdn_write_result=STD_OK;''')
for f,typ,field,req in [('MRC_UpdateCellVoltageValidation','DATA_BLOCK_CELL_VOLTAGE_s','cellVoltage_mV','F2-LLR-ALG-080-07'),('MRC_UpdateCellTemperatureValidation','DATA_BLOCK_CELL_TEMPERATURE_s','cellTemperature_ddegC','F2-LLR-ALG-080-07')]:
 n='001' if 'Voltage' in f else '002'
 add(module,req,n,f,'output header distinct from input','payload123','copy payload; preserve output header',reset+f'''{typ} a={{0}},b={{0}};a.{field}[0][0][0]=123;a.header.timestamp=99;b.header.timestamp=42;DATA_BLOCK_HEADER_s old=b.header;PST_EQ({f}(&a,&b),STD_OK);PST_EQ(b.{field}[0][0][0],123);PST_EQ(memcmp(&b.header,&old,sizeof(old)),0);''')
add(module,'F2-LLR-ALG-080-10','001','MRC_ValidateCellVoltage','only Base valid','all Base3000/red invalid','valid count=N; sum=N*3000;STD_OK',reset+'''
DATA_BLOCK_CELL_VOLTAGE_s a={0},b={0},out={0};memset(&b.invalidCellVoltage,1,sizeof(b.invalidCellVoltage));for(unsigned s=0;s<BS_NR_OF_STRINGS;s++)for(unsigned m=0;m<BS_NR_OF_MODULES_PER_STRING;m++)for(unsigned c=0;c<BS_NR_OF_CELL_BLOCKS_PER_MODULE;c++)a.cellVoltage_mV[s][m][c]=3000;
PST_EQ(MRC_ValidateCellVoltage(&a,&b,&out),STD_OK);PST_EQ(out.nrValidCellVoltages[0],BS_NR_OF_CELL_BLOCKS_PER_STRING);PST_EQ(out.stringVoltage_mV[0],3000*BS_NR_OF_CELL_BLOCKS_PER_STRING);PST_EQ(out.cellVoltage_mV[0][0][0],3000);''')
manifest[-1]['Requirement ID']+='\nF2-LLR-ALG-080-08'
add(module,'F2-LLR-ALG-080-09','001','MRC_ValidateCellTemperature','only Red valid','Base invalid/Red200','STD_OK;temperature200;countN',reset+'''
DATA_BLOCK_CELL_TEMPERATURE_s a={0},b={0},out={0};memset(&a.invalidCellTemperature,1,sizeof(a.invalidCellTemperature));for(unsigned s=0;s<BS_NR_OF_STRINGS;s++)for(unsigned m=0;m<BS_NR_OF_MODULES_PER_STRING;m++)for(unsigned t=0;t<BS_NR_OF_TEMP_SENSORS_PER_MODULE;t++)b.cellTemperature_ddegC[s][m][t]=200;
PST_EQ(MRC_ValidateCellTemperature(&a,&b,&out),STD_OK);PST_EQ(out.nrValidTemperatures[0],BS_NR_OF_TEMP_SENSORS_PER_STRING);PST_EQ(out.cellTemperature_ddegC[0][0][0],200);''')
add(module,'F2-LLR-ALG-080-20','001','MRC_ValidateCurrentMeasurement','new valid current','1000mA timestamp1','string/pack1000mA valid',reset+'''DATA_BLOCK_CURRENT_s c={0};c.timestamp[0]=1;c.current_mA[0]=1000;pst_tick=1;MRC_ValidateCurrentMeasurement(&c);PST_EQ(mrc_tablePackValues.stringCurrent_mA[0],1000);PST_EQ(mrc_tablePackValues.packCurrent_mA,1000);PST_EQ(mrc_tablePackValues.invalidPackCurrent,0);''')
manifest[-1]['Requirement ID']+='\nF2-LLR-ALG-080-21'
add(module,'F2-LLR-ALG-080-16','001','MRC_ValidateStringVoltageMeasurement','AFE all valid;V1 unavailable','AFE54000','string54000 valid',reset+'''DATA_BLOCK_SYSTEM_VOLTAGE_1_s v={0};DATA_BLOCK_CELL_VOLTAGE_s a={0};a.nrValidCellVoltages[0]=BS_NR_OF_CELL_BLOCKS_PER_STRING;a.stringVoltage_mV[0]=54000;MRC_ValidateStringVoltageMeasurement(&v,&a);PST_EQ(mrc_tablePackValues.stringVoltage_mV[0],54000);PST_EQ(mrc_tablePackValues.invalidStringVoltage[0],0);''')
add(module,'F2-LLR-ALG-080-17','001','MRC_ValidateStringVoltageMeasurement','V1 unavailable;5 invalid cells','valid sum39000/average3000','estimated54000 valid',reset+'''DATA_BLOCK_SYSTEM_VOLTAGE_1_s v={0};DATA_BLOCK_CELL_VOLTAGE_s a={0};a.nrValidCellVoltages[0]=BS_NR_OF_CELL_BLOCKS_PER_STRING-5;a.stringVoltage_mV[0]=3000*(BS_NR_OF_CELL_BLOCKS_PER_STRING-5);mrc_tableMinimumMaximumValues.averageCellVoltage_mV[0]=3000;MRC_ValidateStringVoltageMeasurement(&v,&a);PST_EQ(mrc_tablePackValues.stringVoltage_mV[0],3000*BS_NR_OF_CELL_BLOCKS_PER_STRING);PST_EQ(mrc_tablePackValues.invalidStringVoltage[0],0);''')
add(module,'F2-LLR-ALG-080-18','001','MRC_ValidateBatteryVoltageMeasurement','no connected strings;one valid','string54000 valid','battery54000 valid',reset+'''mrc_tablePackValues.stringVoltage_mV[0]=54000;MRC_ValidateBatteryVoltageMeasurement();PST_EQ(mrc_tablePackValues.batteryVoltage_mV,54000);PST_EQ(mrc_tablePackValues.invalidBatteryVoltage,0);''')
add(module,'F2-LLR-ALG-080-19','001','MRC_ValidateHighVoltageBusMeasurement','closed;V3 latest valid','V3=54000 timestamp1','HV54000 valid',reset+'''DATA_BLOCK_SYSTEM_VOLTAGE_3_s v={0};v.timestamp[0]=1;v.highVoltage_mV[0]=54000;pst_tick=1;pst_closed=true;MRC_ValidateHighVoltageBusMeasurement(&v);PST_EQ(mrc_tablePackValues.highVoltageBusVoltage_mV,54000);PST_EQ(mrc_tablePackValues.invalidHvBusVoltage,0);''')

add('config_bal_cfg','F2-LLR-ALG-063-01','001','BAL_GetBalancingThreshold_mV','initial state','get','default threshold','pst_reset_contract();bal_threshold_mV=BAL_DEFAULT_THRESHOLD_mV;PST_EQ(BAL_GetBalancingThreshold_mV(),BAL_DEFAULT_THRESHOLD_mV);')
add('plausibility_plausibility','F2-LLR-ALG-070-04','001','PL_CheckVoltageSpread','all valid3000','one3400;mean3000','cell0 invalid;others valid;NOT_OK','''pst_reset_contract();DATA_BLOCK_CELL_VOLTAGE_s v={0};DATA_BLOCK_MIN_MAX_s m={0};m.averageCellVoltage_mV[0]=3000;for(unsigned c=0;c<BS_NR_OF_CELL_BLOCKS_PER_MODULE;c++)v.cellVoltage_mV[0][0][c]=3000;v.cellVoltage_mV[0][0][0]=3400;PST_EQ(PL_CheckVoltageSpread(&v,&m),STD_NOT_OK);PST_EQ(v.invalidCellVoltage[0][0][0],true);PST_EQ(v.invalidCellVoltage[0][0][1],false);''')
add('algorithm_state_estimation_soc_counting_soc_counting','F2-LLR-ALG-008-05','001','SE_InitializeStateOfCharge','FRAM values25,20,30;throughput2,3;manual','valid string0','restored five fields;initialized;current timestamp10','''pst_reset_contract();memset(&soc_state,0,sizeof(soc_state));memset(&fram_soc,0,sizeof(fram_soc));fram_soc.averageSoc_perc[0]=25;fram_soc.minimumSoc_perc[0]=20;fram_soc.maximumSoc_perc[0]=30;fram_soc.chargeThroughput_As[0]=2;fram_soc.dischargeThroughput_As[0]=3;extern DATA_BLOCK_CURRENT_s pst_current;memset(&pst_current,0,sizeof(pst_current));pst_current.timestamp[0]=10;DATA_BLOCK_SOC_s s={0};SE_InitializeStateOfCharge(&s,false,0);PST_EQ(s.averageSoc_perc[0],25);PST_EQ(s.minimumSoc_perc[0],20);PST_EQ(s.maximumSoc_perc[0],30);PST_EQ(s.chargeThroughput_As[0],2);PST_EQ(s.dischargeThroughput_As[0],3);PST_EQ(soc_state.socInitialized,true);PST_EQ(soc_state.previousTimestamp[0],10);''')
add('algorithm_algorithm','F2-LLR-ALG-036-07','001','ALGO_MainFunction','reinit requested;cycle0','two main calls','first UNINITIALIZED;next initialized RUNNING','''reset_algorithm();algo_algorithms[0].cycleTime_ms=0;algo_algorithms[0].state=ALGO_REINIT_REQUESTED;ALGO_MainFunction();PST_EQ(algo_algorithms[0].state,ALGO_UNINITIALIZED);PST_EQ(algo_initializationRequested,true);ALGO_MainFunction();PST_EQ(algo_algorithms[0].state,ALGO_RUNNING);''')

(HERE/'config/application_host.json').write_text(json.dumps(cfg,indent=2),encoding='utf-8')
(HERE/'requirements/case-manifest-application.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
print('Gap supplements:',len(manifest),'specifications')
